#include <stdint.h>
#include <stdio.h>

#define USART3_IRQ 39

void USART3_IRQHandler(void);
int main(void)
{
	//1.Manually pend the pending bit for USART3 IRQ number in NVIC
	uint32_t *pISR1 = (uint32_t*)0xE000E204;
	*pISR1 |= (1 << (USART3_IRQ % 32));

	//2.Enable USART3 IRQ number in NVIC
	uint32_t *pISER1 = (uint32_t*)0xE000E104;
	*pISER1	 |= (1 << (USART3_IRQ % 32));

    /* Loop forever */
	for(;;);
}

void USART3_IRQHandler(void){
	//when entered here, the pending register bit will be cleared, because the interrupt is served
	printf("Entered USART3 Interrupt Request\n");
}
